    <script src="{{ asset('theme/assets/plugins/quill/quill.js') }}"></script>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            document.querySelector('#quotation-footnote-editor').closest('.card').before(document.getElementById('other-payments-card'));
            const garage = { lat: Number(@json($business->garage_latitude ?? 13.1391)), lng: Number(@json($business->garage_longitude ?? 123.7438)) };
            const decodeBase64 = (content) => new TextDecoder().decode(Uint8Array.from(atob(content), character => character.charCodeAt(0)));
            const footnoteContent = document.getElementById('quotation-footnote-content');
            const editorOptions = { theme: 'snow', modules: { toolbar: [['bold', 'italic', 'underline', 'strike'], [{ header: [1, 2, 3, false] }], [{ list: 'ordered' }, { list: 'bullet' }], ['blockquote', 'link'], ['clean']] } };
            const footnoteEditor = new Quill('#quotation-footnote-editor', editorOptions);
            footnoteEditor.clipboard.dangerouslyPasteHTML(footnoteContent.value);
            footnoteEditor.on('text-change', () => footnoteContent.value = footnoteEditor.root.innerHTML === '<p><br></p>' ? '' : footnoteEditor.root.innerHTML);
            document.getElementById('quotation-footnote').addEventListener('change', event => { const option = event.target.selectedOptions[0]; footnoteEditor.clipboard.dangerouslyPasteHTML(option?.dataset.content ? decodeBase64(option.dataset.content) : ''); });
            document.querySelectorAll('.apply-footnote').forEach(button => button.addEventListener('click', () => { const selector = document.getElementById('quotation-footnote'); selector.value = button.dataset.id; footnoteEditor.clipboard.dangerouslyPasteHTML(decodeBase64(button.dataset.content)); }));
            const footnoteLibraryContent = document.getElementById('footnote-library-content');
            const footnoteLibraryEditor = new Quill('#footnote-library-editor', editorOptions);
            footnoteLibraryEditor.on('text-change', () => footnoteLibraryContent.value = footnoteLibraryEditor.root.innerHTML === '<p><br></p>' ? '' : footnoteLibraryEditor.root.innerHTML);
            const list = document.getElementById('itinerary-list'); let draggedItem; let targetItem; let targetBoundary; let selectedLocation;
            const otherPaymentsList = document.getElementById('other-payments-list'); const otherPaymentModal = bootstrap.Modal.getOrCreateInstance(document.getElementById('other-payment-modal')); const otherPaymentForm = document.getElementById('other-payment-form'); const otherPaymentName = document.getElementById('other-payment-name'); const otherPaymentAmount = document.getElementById('other-payment-amount'); let editingOtherPayment = null; let draggedPayment;
            const otherPayments = @json(old('other_payments', $editingQuotation?->other_payments ?? []));
            const renderOtherPayments = () => { otherPaymentsList.innerHTML = ''; otherPayments.forEach((payment, index) => { const item = document.createElement('div'); item.className = 'other-payment-item border rounded p-2 mb-2 d-flex gap-2 align-items-center'; item.draggable = true; item.innerHTML = `<i class="ti ti-grip-vertical text-muted"></i><strong class="flex-grow-1"></strong><span class="other-payment-amount"></span><button type="button" class="btn btn-sm btn-outline-primary edit-other-payment"><i class="ti ti-edit"></i></button><button type="button" class="btn btn-sm btn-outline-danger remove-other-payment"><i class="ti ti-trash"></i></button><input type="hidden" form="quotation-form" name="other_payments[${index}][name]"><input type="hidden" form="quotation-form" name="other_payments[${index}][amount]">`; item.querySelector('strong').textContent = payment.name; item.querySelector('.other-payment-amount').textContent = peso(Number(payment.amount)); item.querySelector('input[name$="[name]"]').value = payment.name; item.querySelector('input[name$="[amount]"]').value = payment.amount; item.querySelector('.edit-other-payment').addEventListener('click', () => { editingOtherPayment = index; otherPaymentName.value = payment.name; otherPaymentAmount.value = payment.amount; otherPaymentModal.show(); }); item.querySelector('.remove-other-payment').addEventListener('click', () => { otherPayments.splice(index, 1); renderOtherPayments(); updateTotals(); }); item.addEventListener('dragstart', () => { draggedPayment = item; }); item.addEventListener('dragover', event => event.preventDefault()); item.addEventListener('drop', event => { event.preventDefault(); if (draggedPayment !== item) { const from = [...otherPaymentsList.children].indexOf(draggedPayment); const to = [...otherPaymentsList.children].indexOf(item); const [payment] = otherPayments.splice(from, 1); otherPayments.splice(to, 0, payment); renderOtherPayments(); updateTotals(); } }); otherPaymentsList.append(item); }); if (!otherPayments.length) otherPaymentsList.innerHTML = '<p class="small text-muted mb-0">No other payments added.</p>'; };
            otherPaymentForm.addEventListener('submit', event => { event.preventDefault(); const payment = { name: otherPaymentName.value.trim(), amount: Number(otherPaymentAmount.value) }; if (!payment.name || !Number.isFinite(payment.amount) || payment.amount < 0) return; if (editingOtherPayment === null) otherPayments.push(payment); else otherPayments[editingOtherPayment] = payment; editingOtherPayment = null; otherPaymentForm.reset(); otherPaymentModal.hide(); renderOtherPayments(); updateTotals(); });
            document.getElementById('add-other-payment').addEventListener('click', () => { editingOtherPayment = null; otherPaymentForm.reset(); });
            const modal = bootstrap.Modal.getOrCreateInstance(document.getElementById('itinerary-map-modal'));
            const map = L.map('itinerary-map').setView([garage.lat, garage.lng], 13); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '© OpenStreetMap' }).addTo(map); const marker = L.marker([garage.lat, garage.lng], { draggable: true }).addTo(map);
            const peso = (amount) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(amount || 0);
            const items = () => [...list.querySelectorAll('.itinerary-item')];
            const refreshNames = () => items().forEach((item, index) => { item.querySelector('.itinerary-number').textContent = index + 1; item.querySelectorAll('[data-field]').forEach(input => input.name = `itinerary[${index}][${input.dataset.field}]`); });
            const updateTotals = async () => {
                const stops = items().map(item => ({ lat: Number(item.dataset.latitude), lng: Number(item.dataset.longitude) })).filter(stop => Number.isFinite(stop.lat) && Number.isFinite(stop.lng)); const start = { lat: Number(document.getElementById('itinerary-start-latitude').value), lng: Number(document.getElementById('itinerary-start-longitude').value) }; const end = { lat: Number(document.getElementById('itinerary-end-latitude').value), lng: Number(document.getElementById('itinerary-end-longitude').value) }; let distance = 0; let travelSeconds = 0;
                if (stops.length && Number.isFinite(start.lat) && Number.isFinite(start.lng) && Number.isFinite(end.lat) && Number.isFinite(end.lng)) { try { const points = [start, ...stops, end].map(point => `${point.lng},${point.lat}`).join(';'); const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${points}?overview=false`); const route = response.ok ? (await response.json()).routes?.[0] : null; distance = (route?.distance || 0) / 1000; travelSeconds = route?.duration || 0; } catch (error) { distance = 0; travelSeconds = 0; } }
                const carOption = document.getElementById('quotation-car').selectedOptions[0]; const rateOption = document.getElementById('quotation-rate').selectedOptions[0]; const driverOption = document.getElementById('quotation-driver').selectedOptions[0]; const vehicleRate = Number(rateOption?.dataset.value || 0); const driverRate = Number(driverOption?.dataset.rate || 0); const allIn = document.querySelector('[name="package_type"]:checked').value === 'all_in'; const consumption = Number(carOption?.dataset.consumption || 0); const fuelPrice = Number(carOption?.dataset.fuelPrice || 0); const rawDistanceRate = allIn && consumption > 0 ? distance / consumption * fuelPrice : 0; const distanceRate = rawDistanceRate > 0 ? Math.ceil(rawDistanceRate / 100) * 100 : 0;
                const otherPaymentsTotal = otherPayments.reduce((total, payment) => total + Number(payment.amount || 0), 0); const hiddenCharges = Number(document.getElementById('hidden-charges').value || 0); const travelHours = Math.floor(travelSeconds / 3600); const travelMinutes = Math.round((travelSeconds % 3600) / 60); const formattedTravelTime = travelHours ? `${travelHours} hr${travelHours === 1 ? '' : 's'} ${travelMinutes} min` : `${travelMinutes} min`; document.getElementById('total-distance').value = distance.toFixed(2); document.getElementById('vehicle-rate').textContent = peso(vehicleRate); document.getElementById('driver-rate').textContent = peso(driverRate); document.getElementById('distance-rate').textContent = peso(distanceRate); document.getElementById('other-payments-total').textContent = peso(otherPaymentsTotal); document.getElementById('hidden-charges-total').textContent = peso(hiddenCharges); document.getElementById('distance-km').textContent = `${distance.toFixed(2)} km`; document.getElementById('travel-time').textContent = formattedTravelTime; document.getElementById('fuel-note').textContent = allIn ? '(fuel included)' : '(fuel excluded)'; document.getElementById('total-rate').textContent = peso(vehicleRate + driverRate + distanceRate + otherPaymentsTotal + hiddenCharges);
            };
            const setMapLocation = async (location) => { marker.setLatLng(location); map.setView(location, 15); selectedLocation = { lat: location.lat, lng: location.lng }; document.getElementById('itinerary-selected-address').textContent = 'Getting address…'; document.getElementById('save-itinerary-location').disabled = true; try { const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${location.lat}&lon=${location.lng}`); const result = response.ok ? await response.json() : null; selectedLocation.address = result?.display_name || `Pinned location (${location.lat.toFixed(6)}, ${location.lng.toFixed(6)})`; document.getElementById('itinerary-selected-address').textContent = selectedLocation.address; document.getElementById('save-itinerary-location').disabled = false; } catch (error) { document.getElementById('itinerary-selected-address').textContent = 'Could not find this address. Please select another point.'; } };
            const applyLocation = (item, location) => { item.dataset.latitude = location.latitude; item.dataset.longitude = location.longitude; item.querySelector('.itinerary-address').value = location.title ? `${location.title} — ${location.address}` : location.address; item.querySelector('[data-field="address"]').value = location.address; item.querySelector('[data-field="latitude"]').value = location.latitude; item.querySelector('[data-field="longitude"]').value = location.longitude; item.querySelector('[data-field="title"]').value = location.title || ''; };
            const addItem = (location = null) => { const item = document.createElement('div'); item.className = 'itinerary-item border rounded p-3 mb-2'; item.draggable = true; item.innerHTML = '<div class="d-flex gap-2 align-items-center"><i class="ti ti-grip-vertical text-muted"></i><strong class="itinerary-number"></strong><input class="form-control itinerary-address" readonly required placeholder="Click to set a location"><input type="hidden" data-field="address"><input type="hidden" data-field="title"><input type="hidden" data-field="latitude"><input type="hidden" data-field="longitude"><button type="button" class="btn btn-outline-danger remove-itinerary"><i class="ti ti-x"></i></button></div>'; item.querySelector('.itinerary-address').addEventListener('click', () => { targetItem = item; targetBoundary = null; document.getElementById('itinerary-location-title-group').classList.remove('d-none'); document.getElementById('itinerary-location-title').value = item.querySelector('[data-field="title"]').value; modal.show(); setTimeout(() => map.invalidateSize(), 250); }); item.querySelector('.remove-itinerary').addEventListener('click', () => { item.remove(); refreshNames(); updateTotals(); }); item.addEventListener('dragstart', () => { draggedItem = item; }); item.addEventListener('dragover', event => event.preventDefault()); item.addEventListener('drop', event => { event.preventDefault(); if (draggedItem !== item) list.insertBefore(draggedItem, item); refreshNames(); updateTotals(); }); list.append(item); if (location) applyLocation(item, location); refreshNames(); return item; };
            document.getElementById('add-itinerary').addEventListener('click', () => addItem()); document.getElementById('quotation-car').addEventListener('change', updateTotals); document.getElementById('quotation-driver').addEventListener('change', updateTotals); document.querySelectorAll('[name="package_type"]').forEach(input => input.addEventListener('change', updateTotals)); map.on('click', event => setMapLocation(event.latlng)); marker.on('dragend', () => setMapLocation(marker.getLatLng())); document.getElementById('itinerary-search').addEventListener('input', async event => { const results = document.getElementById('itinerary-search-results'); if (event.target.value.trim().length < 3) { results.innerHTML = ''; return; } try { const response = await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q=${encodeURIComponent(event.target.value)}`); const locations = response.ok ? await response.json() : []; results.innerHTML = locations.map(location => `<button type="button" class="list-group-item list-group-item-action" data-lat="${location.lat}" data-lng="${location.lon}">${location.display_name}</button>`).join(''); results.querySelectorAll('button').forEach(button => button.addEventListener('click', () => setMapLocation({ lat: Number(button.dataset.lat), lng: Number(button.dataset.lng) }))); } catch (error) { results.innerHTML = ''; } }); document.getElementById('save-itinerary-location').addEventListener('click', async () => { const title = document.getElementById('itinerary-location-title').value.trim(); if (!targetItem || !selectedLocation?.address || !title) { document.getElementById('itinerary-location-title').focus(); return; } const location = { title, address: selectedLocation.address, latitude: selectedLocation.lat, longitude: selectedLocation.lng }; applyLocation(targetItem, location); try { await fetch(@json(route('business.quotations.saved-locations.store')), { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': @json(csrf_token()), 'Accept': 'application/json' }, body: JSON.stringify(location) }); } catch (error) { } modal.hide(); updateTotals(); }); document.querySelectorAll('.saved-location').forEach(button => { const location = { title: button.dataset.title, address: button.dataset.address, latitude: button.dataset.latitude, longitude: button.dataset.longitude }; button.addEventListener('click', () => { addItem(location); updateTotals(); }); button.addEventListener('dragstart', () => { draggedItem = null; button.dataset.dragging = 'true'; }); button.addEventListener('dragend', () => delete button.dataset.dragging); }); list.addEventListener('dragover', event => event.preventDefault()); list.addEventListener('drop', event => { const saved = document.querySelector('.saved-location[data-dragging="true"]'); if (saved) { addItem({ title: saved.dataset.title, address: saved.dataset.address, latitude: saved.dataset.latitude, longitude: saved.dataset.longitude }); updateTotals(); } });
            document.querySelectorAll('.itinerary-boundary-input').forEach(input => input.addEventListener('click', () => { targetItem = null; targetBoundary = input.dataset.boundary; document.getElementById('itinerary-location-title-group').classList.add('d-none'); document.getElementById('itinerary-location-title').value = ''; modal.show(); setTimeout(() => map.invalidateSize(), 250); }));
            document.getElementById('save-itinerary-location').addEventListener('click', () => { if (!targetBoundary || !selectedLocation?.address) return; document.getElementById(`itinerary-${targetBoundary}-address`).value = selectedLocation.address; document.getElementById(`itinerary-${targetBoundary}-address-value`).value = selectedLocation.address; document.getElementById(`itinerary-${targetBoundary}-latitude`).value = selectedLocation.lat; document.getElementById(`itinerary-${targetBoundary}-longitude`).value = selectedLocation.lng; targetBoundary = null; modal.hide(); updateTotals(); });
            const savedLocationEditModal = bootstrap.Modal.getOrCreateInstance(document.getElementById('edit-saved-location-modal'));
            const savedLocationUpdateUrl = @json(route('business.quotations.saved-locations.update', ['savedLocation' => '__LOCATION__']));
            document.querySelectorAll('.edit-saved-location').forEach(button => button.addEventListener('click', () => { document.getElementById('edit-saved-location-form').action = savedLocationUpdateUrl.replace('__LOCATION__', button.dataset.id); document.getElementById('edit-saved-title').value = button.dataset.title; document.getElementById('edit-saved-address').value = button.dataset.address; document.getElementById('edit-saved-latitude').value = button.dataset.latitude; document.getElementById('edit-saved-longitude').value = button.dataset.longitude; savedLocationEditModal.show(); }));
            const footnoteModal = bootstrap.Modal.getOrCreateInstance(document.getElementById('footnote-modal')); const footnoteUpdateUrl = @json(route('business.quotations.footnotes.update', ['footnote' => '__FOOTNOTE__']));
            document.getElementById('add-footnote-button').addEventListener('click', () => { const form = document.getElementById('footnote-form'); form.action = @json(route('business.quotations.footnotes.store')); form.querySelector('input[name="_method"]')?.remove(); form.reset(); footnoteLibraryEditor.setText(''); });
            document.querySelectorAll('.edit-footnote').forEach(button => button.addEventListener('click', () => { const form = document.getElementById('footnote-form'); form.action = footnoteUpdateUrl.replace('__FOOTNOTE__', button.dataset.id); form.querySelector('input[name="_method"]')?.remove(); form.insertAdjacentHTML('afterbegin', '<input type="hidden" name="_method" value="PUT">'); document.getElementById('footnote-title').value = button.dataset.title; footnoteLibraryEditor.clipboard.dangerouslyPasteHTML(decodeBase64(button.dataset.content)); footnoteModal.show(); }));
            document.getElementById('hidden-charges').addEventListener('input', updateTotals);
            const vehicleRateSelect = document.getElementById('quotation-rate'); const selectedVehicleRate = @json(old('vehicle_rate_name', $editingQuotation?->vehicle_rate_name)); const loadVehicleRates = () => { const carOption = document.getElementById('quotation-car').selectedOptions[0]; const rates = carOption?.dataset.rates ? JSON.parse(carOption.dataset.rates) : []; vehicleRateSelect.replaceChildren(); rates.forEach(rate => { const option = new Option(`${rate.name} — ${peso(rate.value)}`, rate.name); option.dataset.value = rate.value; option.selected = rate.name === selectedVehicleRate; vehicleRateSelect.add(option); }); if (!rates.length) vehicleRateSelect.add(new Option('No rates available', '')); vehicleRateSelect.disabled = rates.length === 0; updateTotals(); }; document.getElementById('quotation-car').addEventListener('change', loadVehicleRates); vehicleRateSelect.addEventListener('change', updateTotals);
            const existingItinerary = @json($editingQuotation?->itinerary ?? []); if (existingItinerary.length) { existingItinerary.forEach(location => addItem(location)); } else { addItem(); } renderOtherPayments(); loadVehicleRates();
        });
    </script>
@endpush
